     "Lower limit a = 0 (from y = 0, when t = 0)",
     "Upper limit b = ½ (from y = 2: 2t² + 3t = 2 ⇒ (2t − 1)(t + 2) = 0 ⇒ t = ½, rejecting t = −2)",
